package com.hms.website;
import com.hms.tenancy.*; import jakarta.validation.Valid; import java.util.UUID; import org.springframework.web.bind.annotation.*;
@RestController @RequestMapping("/api/hospitals/{tenantSlug}/website/settings") public class WebsiteSettingsController { private final TenantRepository tenants; private final WebsiteSettingsRepository settings; public WebsiteSettingsController(TenantRepository t,WebsiteSettingsRepository s){tenants=t;settings=s;} @GetMapping public WebsiteSettings get(@PathVariable String tenantSlug){return settings.findByTenantId(tenant(tenantSlug)).orElseThrow(()->new IllegalArgumentException("Website settings not configured"));} @PutMapping public WebsiteSettings update(@PathVariable String tenantSlug,@Valid @RequestBody UpdateWebsiteSettingsRequest r){UUID t=tenant(tenantSlug);WebsiteSettings s=settings.findByTenantId(t).orElseGet(()->new WebsiteSettings(t,r));s.apply(r);return settings.save(s);} private UUID tenant(String s){return tenants.findBySlug(s).map(Tenant::getId).orElseThrow(()->new TenantNotFoundException(s));} }
